import { StatusEnum } from '@/enum/stateTransactionEnum';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { LocalStorageService } from '@/storages/local_storage_service';

export async function getOrders(
  id: string,
): Promise<{ status: string; ref: string }> {
  if (USE_SEED_DATA) return seed.getOrders(id);

  // Détermine l'origin à utiliser
  const origin = window.origin;

  const response = await fetch(`${URLS.GET_ORDERS}/${id}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
    },
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const json = await response.json();
  if (json.etat === false) {
    return { status: StatusEnum.REJECTED, ref: StatusEnum.REJECTED };
  } else if (json.etat && typeof window !== 'undefined' && json.result.client) {
    const { access_token, ...rest } = json.result.client;
    LocalStorageService.saveToken(access_token);
    json.result.client = rest;
  }
  return json.result;
}
