import { LocalStorageService } from '@/storages/local_storage_service';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { AuthResponse } from '@/types';

export async function sendSubscriptionOtp({
  numberTel,
}: {
  numberTel: string;
}): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.sendSubscriptionOtp();

  let token;

  // Vérifie si nous sommes côté client avant d'accéder à localStorage
  if (typeof window !== 'undefined') {
    token = LocalStorageService.getToken();
  }
  const origin = window.origin;

  const response = await fetch(URLS.SEND_SUBSCRIPTION_OTP, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
      ...(token && { Authorization: token }),
    },
    body: JSON.stringify({ numberTel }),
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => null);
    throw new Error(errorData?.message || "Échec de l'envoi du code OTP");
  }
  return (await response.json()) as AuthResponse;
}
