import { LocalStorageService } from '@/storages/local_storage_service';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { PricingType } from '@/types/PricingType';
import { deleteAllNotificationsIndexDb } from '@/storages/indexed_db_service';
import { AuthResponse } from '@/types';

export async function getPricing(): Promise<PricingType[]> {
  if (USE_SEED_DATA) return seed.getPricing();

  let token;

  // Vérifie si nous sommes côté client avant d'accéder à localStorage
  if (typeof window !== 'undefined') {
    token = LocalStorageService.getToken(); // Accéder à localStorage uniquement côté client
  }
  // Détermine l'origin à utiliser
  const origin = window.origin;

  const response = await fetch(URLS.GET_PRICING, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
      ...(token && { Authorization: token }),
    },
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const json = (await response.json()) as AuthResponse;
  if (json.etat) {
    const pricings = json.result as PricingType[];
    return pricings;
  } else {
    LocalStorageService.clearData();
    deleteAllNotificationsIndexDb();
  }
  return [];
}
